export const PHYSICS=Object.freeze({cruise:248,fast:358,slow:95,loadTime:.34,bailTime:.62,gravity:1050,popMin:205,popMax:440});
export const clamp=(v,lo,hi)=>Math.min(hi,Math.max(lo,v));
export const COURSE_LENGTH=5600;
export const LINE_NAME='THE TABLE';
const course=[
  {x:760,w:92,h:18,type:'box',name:'START CURB',material:'wood',feature:'curb'},
  {x:1390,w:240,h:42,type:'box',name:'TABLE LEDGE',material:'wood',feature:'ledge'},
  {x:2180,w:150,h:0,type:'gap',name:'TABLE GAP',material:'gap',feature:'gap'},
  {x:3030,w:140,h:34,type:'rail',name:'LOW RAIL',material:'metal',feature:'rail'},
  {x:3920,w:180,h:30,type:'box',name:'LANDING BLOCK',material:'concrete',feature:'landing'},
  {x:4760,w:300,h:48,rise:230,type:'ramp',name:'RUN OUT',material:'cardboard',feature:'finish'}
];
export function obstaclesBetween(a,b){const out=[];for(let n=Math.max(0,Math.floor(a/COURSE_LENGTH));n<=Math.floor(b/COURSE_LENGTH);n++)for(const o of course){const x=o.x+n*COURSE_LENGTH;if(x+o.w>=a&&x<=b)out.push({...o,x,id:`${n}:${o.x}`});}return out;}
export function surfaceAt(x){for(const o of obstaclesBetween(x-400,x+1)){if(x>=o.x&&x<o.x+o.w&&o.type!=='gap'&&o.type!=='rail'){const rise=o.rise||o.w;const h=o.type==='ramp'?Math.min(o.h,(x-o.x)/rise*o.h):o.h;return {h,slope:o.type==='ramp'&&x<o.x+rise?Math.atan2(o.h,rise):0,obstacle:o};}}return {h:0,slope:0,obstacle:null};}
export function needsLandscape(w,h){return w<=h;}

export class FingerboardGame{
  constructor(){this.events=[];this.reset();}
  emit(type,details={}){this.events.push({type,...details});}
  drainEvents(){const list=this.events;this.events=[];return list;}
  reset(){this.mode='ready';this.phase='roll';this.x=220;this.y=0;this.vx=PHYSICS.cruise;this.vy=0;this.angle=0;this.spin=0;this.charge=0;this.rear=false;this.front=false;this.steer=0;this.tilt=0;this.catch=false;this.score=0;this.combo=0;this.lineScore=0;this.lineStreak=0;this.bestLine=0;this.completedLines=0;this.lineBailed=false;this.lineFinishLap=-1;this.ollies=0;this.kickflips=0;this.heelflips=0;this.popShuvits=0;this.threeSixtyShuvits=0;this.oneEighties=0;this.varialKickflips=0;this.varialHeelflips=0;this.treFlips=0;this.inwardHeelflips=0;this.fiftyFifties=0;this.boardslides=0;this.bails=0;this.flip=0;this.flipVelocity=0;this.flipComplete=false;this.shuv=0;this.shuvVelocity=0;this.shuvComplete=false;this.bodySpin=0;this.bodySpinVelocity=0;this.bodySpinComplete=false;this.trick=null;this.grind=null;this.grindObstacle=null;this.grindIntent=null;this.grindYaw=0;this.demoAssist=false;this.elapsed=0;this.bailRemaining=0;this.startX=this.x;this.airStartX=this.x;this.airStartY=0;this.airPeak=0;this.airObstacles=new Set();this.clearedFeatures=new Set();this.hasPop=false;this.events=[];this.lastLanding=0;this.emit('reset');}
  start(){this.mode='playing';}
  pause(){if(this.mode==='playing'){this.cancelInput();this.mode='paused';}}
  resume(){if(this.mode==='paused')this.mode='playing';}
  setFront(active,steer=0,tilt=0){this.front=active;this.steer=active?clamp(steer,-1,1):0;this.tilt=active?clamp(tilt,-1,1):0;}
  releaseFront(){this.front=false;this.tilt=0;}
  rearDown(){if(this.mode!=='playing'||this.phase==='bail')return;this.rear=true;if(this.phase==='air'){this.catch=true;if((this.trick==='kickflip'||this.trick==='heelflip'||this.trick==='varialkickflip'||this.trick==='varialheelflip'||this.trick==='treflip'||this.trick==='inwardheelflip')&&!this.flipComplete)this.flipVelocity=0;if((this.trick==='popshuvit'||this.trick==='360shuvit'||this.trick==='varialkickflip'||this.trick==='varialheelflip'||this.trick==='treflip'||this.trick==='inwardheelflip')&&!this.shuvComplete)this.shuvVelocity=0;if(this.trick==='180'&&!this.bodySpinComplete)this.bodySpinVelocity=0;this.emit('catch');}else if(this.phase==='roll'){this.phase='load';this.charge=0;}}
  rearUp(flick=1){if(!this.rear)return;this.rear=false;if(this.phase==='load'&&this.mode==='playing'){const power=clamp(this.charge/PHYSICS.loadTime,0,1);this.vy=(PHYSICS.popMin+(PHYSICS.popMax-PHYSICS.popMin)*power)*clamp(flick,.9,1.12);this.angle=clamp(this.angle+.11,.12,.38);this.spin=.38+.18*power;this.phase='air';this.y+=1;this.airStartX=this.x;this.airStartY=this.y;this.airPeak=0;this.airObstacles=new Set();this.hasPop=true;this.charge=0;this.catch=false;this.emit('pop',{power});}else if(this.phase==='air'){this.catch=false;}}
  kickflip(){if(this.mode!=='playing'||this.phase!=='air'||!this.hasPop||this.catch)return false;if(this.trick==='popshuvit'){this.trick='varialkickflip';this.flip=0;this.flipVelocity=19.5;this.flipComplete=false;this.emit('varialkickflip');return true;}if(this.trick==='360shuvit'){this.trick='treflip';this.flip=0;this.flipVelocity=19.5;this.flipComplete=false;this.emit('treflip');return true;}if(this.trick)return false;this.trick='kickflip';this.flip=0;this.flipVelocity=19.5;this.flipComplete=false;this.emit('kickflip');return true;}
  heelflip(){if(this.mode!=='playing'||this.phase!=='air'||!this.hasPop||this.catch)return false;if(this.trick==='popshuvit'){this.trick='varialheelflip';this.flip=0;this.flipVelocity=-19.5;this.flipComplete=false;this.emit('varialheelflip');return true;}if(this.trick==='360shuvit'){this.trick='inwardheelflip';this.flip=0;this.flipVelocity=-19.5;this.flipComplete=false;this.emit('inwardheelflip');return true;}if(this.trick)return false;this.trick='heelflip';this.flip=0;this.flipVelocity=-19.5;this.flipComplete=false;this.emit('heelflip');return true;}
  popShuvit(direction=1){if(this.mode!=='playing'||this.phase!=='air'||!this.hasPop||this.trick||this.catch)return false;this.trick='popshuvit';this.shuv=0;this.shuvVelocity=clamp(direction,-1,1)*12.8;this.shuvComplete=false;this.emit('popshuvit');return true;}
  threeSixtyShuvit(direction=1){if(this.mode!=='playing'||this.phase!=='air'||!this.hasPop||this.trick||this.catch)return false;this.trick='360shuvit';this.shuv=0;this.shuvVelocity=clamp(direction,-1,1)*18.4;this.shuvComplete=false;this.emit('360shuvit');return true;}
  oneEighty(direction=1){if(this.mode!=='playing'||this.phase!=='air'||!this.hasPop||this.trick||this.catch)return false;this.trick='180';this.bodySpin=0;this.bodySpinVelocity=clamp(direction,-1,1)*10.8;this.bodySpinComplete=false;this.emit('180');return true;}
  nearGrindRail(range=150){return obstaclesBetween(this.x-range,this.x+range).find(o=>o.type==='rail'&&o.x+o.w>=this.x-30&&o.x<=this.x+range)||null;}
  boardslide(direction=1){if(this.mode!=='playing'||this.phase!=='air'||!this.hasPop||this.trick||this.catch||!this.nearGrindRail())return false;this.grindIntent='boardslide';this.grindYaw=clamp(direction,-1,1)*Math.PI/2;this.emit('boardslideintent');return true;}
  enterGrind(o,type){this.phase='grind';this.grind=type;this.grindObstacle=o;this.y=o.h;this.vy=0;this.spin=0;this.angle=0;this.catch=true;this.grindYaw=type==='boardslide'?(this.grindYaw||Math.PI/2):0;this.emit('grindstart',{grind:type==='boardslide'?'BOARDSLIDE':'50-50',name:o.name});}
  exitGrind(){if(this.phase!=='grind'||!this.grindObstacle)return;const type=this.grind,rail=this.grindObstacle;const points=type==='boardslide'?320:240;this.score+=points;this.lineScore+=points;this.lineStreak+=1;if(type==='boardslide')this.boardslides++;else this.fiftyFifties++;this.combo++;this.clearedFeatures.add(rail.id);this.emit('grindcomplete',{grind:type==='boardslide'?'BOARDSLIDE':'50-50',name:rail.name,points,lineScore:this.lineScore,lineStreak:this.lineStreak});this.phase='air';this.y=rail.h+1;this.vy=-28;this.airStartY=this.y;this.grind=null;this.grindObstacle=null;this.grindIntent=null;this.grindYaw=0;}
  cancelInput(){this.rear=false;this.catch=false;this.setFront(false);this.charge=0;if(this.phase==='load'){this.phase='roll';this.angle=surfaceAt(this.x).slope;}}
  bail(reason='OFF BALANCE'){if(this.phase==='bail')return;this.phase='bail';this.bailRemaining=PHYSICS.bailTime;this.bails++;this.combo=0;this.lineStreak=0;this.lineBailed=true;this.spin=5.5;this.vy=Math.max(105,this.vy*.2);this.cancelInput();this.emit('bail',{reason});}
  respawn(){const near=obstaclesBetween(this.x-180,this.x+80).find(o=>o.x+o.w>this.x-30);this.x=Math.max(180,near?near.x-380:this.x-250);this.y=surfaceAt(this.x).h;this.angle=0;this.spin=0;this.vy=0;this.vx=PHYSICS.cruise;this.phase='roll';this.cancelInput();this.hasPop=false;this.flip=0;this.flipVelocity=0;this.flipComplete=false;this.shuv=0;this.shuvVelocity=0;this.shuvComplete=false;this.bodySpin=0;this.bodySpinVelocity=0;this.bodySpinComplete=false;this.trick=null;this.grind=null;this.grindObstacle=null;this.grindIntent=null;this.grindYaw=0;this.emit('respawn');}
  land(surface){if(surface.obstacle&&this.hasPop&&this.airStartX<surface.obstacle.x&&!this.clearedFeatures.has(surface.obstacle.id)){this.airObstacles.add(surface.obstacle.id);this.clearedFeatures.add(surface.obstacle.id);this.lineScore+=150;this.emit('featureclear',{id:surface.obstacle.id,name:surface.obstacle.name,feature:surface.obstacle.feature||surface.obstacle.type,points:150,lineScore:this.lineScore});}const error=Math.abs(this.angle-surface.slope);const trick=this.trick;const isFlip=trick==='kickflip'||trick==='heelflip'||trick==='varialkickflip'||trick==='varialheelflip'||trick==='treflip'||trick==='inwardheelflip';const isShuv=trick==='popshuvit'||trick==='360shuvit'||trick==='varialkickflip'||trick==='varialheelflip'||trick==='treflip'||trick==='inwardheelflip';const is180=trick==='180';const flipError=isFlip?Math.abs(Math.abs(this.flip)-Math.PI*2):0;const shuvTarget=(trick==='360shuvit'||trick==='treflip'||trick==='inwardheelflip')?Math.PI*2:Math.PI;const shuvError=isShuv?Math.abs(Math.abs(this.shuv)-shuvTarget):0;const bodyError=is180?Math.abs(Math.abs(this.bodySpin)-Math.PI):0;if(isFlip&&flipError>.72){this.bail('CATCH THE FLIP');return;}if(isShuv&&shuvError>.48){this.bail('CATCH THE SHUV');return;}if(is180&&bodyError>.48){this.bail('FINISH THE 180');return;}if(error>.57){this.bail('LEVEL THE DECK');return;}this.y=surface.h;this.vy=0;this.spin=0;this.angle=surface.slope;this.phase='roll';this.catch=false;this.charge=0;let points=0;const clean=error<.23;if(this.hasPop&&this.airPeak>10){this.ollies++;if(trick==='kickflip')this.kickflips++;else if(trick==='heelflip')this.heelflips++;else if(trick==='popshuvit')this.popShuvits++;else if(trick==='360shuvit')this.threeSixtyShuvits++;else if(trick==='180')this.oneEighties++;else if(trick==='varialkickflip')this.varialKickflips++;else if(trick==='varialheelflip')this.varialHeelflips++;else if(trick==='treflip')this.treFlips++;else if(trick==='inwardheelflip')this.inwardHeelflips++;this.combo++;const clearCount=this.airObstacles.size;const trickBonus=(trick==='treflip'||trick==='inwardheelflip')?520:(trick==='varialkickflip'||trick==='varialheelflip')?380:(trick==='kickflip'||trick==='heelflip')?220:trick==='360shuvit'?280:trick==='popshuvit'?180:trick==='180'?160:0;points=Math.round((clean?100:65)+Math.min(80,this.airPeak*.45)+clearCount*120+trickBonus)*Math.min(4,1+Math.floor((this.combo-1)/3));this.score+=points;this.lineStreak=clean?this.lineStreak+1:0;const linePoints=points+(clean&&this.lineStreak>1?(this.lineStreak-1)*40:0);this.lineScore+=linePoints;this.emit('land',{clean,points,clears:clearCount,combo:this.combo,linePoints,lineScore:this.lineScore,lineStreak:this.lineStreak,trick:trick==='kickflip'?'KICKFLIP':trick==='heelflip'?'HEELFLIP':trick==='popshuvit'?'POP SHUVIT':trick==='360shuvit'?'360 SHUVIT':trick==='180'?'180':trick==='varialkickflip'?'VARIAL KICKFLIP':trick==='varialheelflip'?'VARIAL HEELFLIP':trick==='treflip'?'360 FLIP':trick==='inwardheelflip'?'INWARD HEELFLIP':'OLLIE'});}else this.emit('rollaway');this.hasPop=false;this.flip=0;this.flipVelocity=0;this.flipComplete=false;this.shuv=0;this.shuvVelocity=0;this.shuvComplete=false;this.bodySpin=0;this.bodySpinVelocity=0;this.bodySpinComplete=false;this.trick=null;this.lastLanding=this.elapsed;}
  checkLineFinish(){const lap=Math.floor(this.x/COURSE_LENGTH);const finishX=lap*COURSE_LENGTH+5060;if(this.x<finishX||this.lineFinishLap===lap)return;this.lineFinishLap=lap;if(this.lineScore<=0){this.lineStreak=0;this.lineBailed=false;return;}const clean=!this.lineBailed;const bonus=clean?500:150;this.lineScore+=bonus;this.bestLine=Math.max(this.bestLine,this.lineScore);this.completedLines++;this.score+=bonus;this.emit('linecomplete',{name:LINE_NAME,clean,bonus,lineScore:this.lineScore,bestLine:this.bestLine,completed:this.completedLines});this.lineScore=0;this.lineStreak=0;this.lineBailed=false;}
  update(dt){if(this.mode!=='playing')return;dt=clamp(dt,0,.025);this.elapsed+=dt;if(this.phase==='grind'){const rail=this.grindObstacle;if(!rail){this.phase='air';return;}const target=this.steer>=0?PHYSICS.cruise+(PHYSICS.fast-PHYSICS.cruise)*this.steer:PHYSICS.cruise+(PHYSICS.cruise-PHYSICS.slow)*this.steer;this.vx+=(target-this.vx)*(1-Math.exp(-4*dt));this.x+=this.vx*dt*.84;this.y=rail.h;this.angle*=Math.exp(-18*dt);this.checkLineFinish();if(this.x>=rail.x+rail.w-10)this.exitGrind();return;}if(this.phase==='bail'){this.bailRemaining-=dt;this.vy-=PHYSICS.gravity*dt;this.x+=this.vx*dt*.35;this.y=Math.max(surfaceAt(this.x).h,this.y+this.vy*dt);this.angle+=this.spin*dt;if(this.bailRemaining<=0)this.respawn();return;}
    const target=this.steer>=0?PHYSICS.cruise+(PHYSICS.fast-PHYSICS.cruise)*this.steer:PHYSICS.cruise+(PHYSICS.cruise-PHYSICS.slow)*this.steer;this.vx+=(target-this.vx)*(1-Math.exp(-6*dt));
    const oldX=this.x,oldY=this.y,nextX=this.x+this.vx*dt;const under=surfaceAt(nextX);const oldSurface=surfaceAt(oldX);this.x=nextX;this.checkLineFinish();
    if(this.phase==='roll'||this.phase==='load'){
      const nose=surfaceAt(nextX+28);const pathFeatures=obstaclesBetween(oldX-32,nextX+32);for(const o of pathFeatures){if(o.type==='gap'&&oldX<o.x&&nextX+28>=o.x){this.bail('OLLIE THE GAP');return;}if(o.type==='rail'&&oldX+28<o.x&&nextX+28>=o.x){this.bail('POP THE RAIL');return;}}if(nose.h>this.y+14&&nose.obstacle?.type!=='ramp'){this.bail('POP BEFORE THE LEDGE');return;}
      if(under.h<oldSurface.h-10){this.phase='air';this.vy=0;this.spin=0;this.airStartX=this.x;this.airStartY=this.y;this.airPeak=0;this.airObstacles=new Set();this.hasPop=false;}
      else{this.y=under.h;if(this.phase==='load')this.charge=Math.min(PHYSICS.loadTime,this.charge+dt);const load=this.charge/PHYSICS.loadTime;const targetAngle=under.slope+(this.phase==='load'?load*.19:0);this.angle+=(targetAngle-this.angle)*(1-Math.exp(-20*dt));return;}
    }
    if(this.phase==='air'){
      this.vy-=PHYSICS.gravity*dt;
      if((this.trick==='kickflip'||this.trick==='heelflip'||this.trick==='varialkickflip'||this.trick==='varialheelflip'||this.trick==='treflip'||this.trick==='inwardheelflip')&&!this.flipComplete){this.flip+=this.flipVelocity*dt;if(Math.abs(this.flip)>=Math.PI*2){this.flip=Math.sign(this.flip||1)*Math.PI*2;this.flipVelocity=0;this.flipComplete=true;}}if((this.trick==='popshuvit'||this.trick==='360shuvit'||this.trick==='varialkickflip'||this.trick==='varialheelflip'||this.trick==='treflip'||this.trick==='inwardheelflip')&&!this.shuvComplete){const target=(this.trick==='360shuvit'||this.trick==='treflip'||this.trick==='inwardheelflip')?Math.PI*2:Math.PI;this.shuv+=this.shuvVelocity*dt;if(Math.abs(this.shuv)>=target){this.shuv=Math.sign(this.shuv||1)*target;this.shuvVelocity=0;this.shuvComplete=true;}}if(this.trick==='180'&&!this.bodySpinComplete){this.bodySpin+=this.bodySpinVelocity*dt;if(Math.abs(this.bodySpin)>=Math.PI){this.bodySpin=Math.sign(this.bodySpin||1)*Math.PI;this.bodySpinVelocity=0;this.bodySpinComplete=true;}}this.y+=this.vy*dt;this.airPeak=Math.max(this.airPeak,this.y-this.airStartY);
      const torque=this.tilt*7.4;this.spin+=torque*dt;this.spin*=Math.exp(-(this.catch?13:1.05)*dt);if(this.catch)this.spin+=(under.slope-this.angle)*31*dt;this.angle+=this.spin*dt;this.angle=clamp(this.angle,-1.55,1.55);
      for(const o of obstaclesBetween(oldX-32,nextX+32)){
        const frontY=this.y+Math.sin(this.angle)*28;
        if(o.type==='rail'&&this.hasPop&&(this.front||this.demoAssist||this.grindIntent==='boardslide')&&this.vy<=30&&nextX+24>=o.x&&nextX-24<=o.x+o.w&&this.y>=o.h-6&&this.y<=o.h+18&&Math.abs(this.angle)<.34&&!this.trick){this.enterGrind(o,this.grindIntent==='boardslide'?'boardslide':'5050');return;}
        if((o.type==='box'||o.type==='rail')&&oldX+28<o.x&&nextX+28>=o.x&&frontY<o.h-1){this.bail(o.type==='rail'?'CLEAR THE RAIL':'A LITTLE MORE POP');return;}if(o.type==='rail'&&nextX+24>=o.x&&nextX-24<=o.x+o.w&&this.vy<0&&oldY>=o.h-2&&this.y<o.h-2){if(this.hasPop&&!this.trick&&Math.abs(this.angle)<.5){this.enterGrind(o,this.grindIntent==='boardslide'?'boardslide':'5050');return;}this.bail('CLEAR THE RAIL');return;}
        if(oldX<o.x+o.w&&nextX>=o.x+o.w&&this.airStartX<o.x){const highEnough=o.type==='gap'||this.y>=o.h-2;if(highEnough){this.airObstacles.add(o.id);if(!this.clearedFeatures.has(o.id)){this.clearedFeatures.add(o.id);this.lineScore+=150;this.emit('featureclear',{id:o.id,name:o.name,feature:o.feature||o.type,points:150,lineScore:this.lineScore});}}}
      }
      if(this.y<=under.h){if(this.vy>0&&oldY<under.h-8){this.bail('A LITTLE MORE POP');return;}this.land(under);}
    }
  }
}

export class DualThumbInput{
  constructor(game){this.game=game;this.pointers=new Map();this.roles={front:null,rear:null};}
  down(id,x,y,width,time=0){const role=x<width/2?'front':'rear';if(this.game.mode!=='playing'||this.roles[role]!==null)return false;this.roles[role]=id;this.pointers.set(id,{role,x,y,steer:this.game.steer,lastX:x,lastY:y,lastTime:time,velocity:0,airX:null,airY:null,airTime:null});if(role==='front')this.game.setFront(true,this.game.steer);else this.game.rearDown();return true;}
  move(id,x,y,time=0){const p=this.pointers.get(id);if(!p)return;const elapsed=time-p.lastTime;if(elapsed>0&&elapsed<150)p.velocity=(p.lastY-y)/elapsed;p.lastX=x;p.lastY=y;p.lastTime=time;if(p.role==='front'){let steer=p.steer+(x-p.x)/150,tilt=(p.y-y)/65;if(this.game.phase==='air'&&this.game.hasPop){if(p.airTime===null){p.airX=x;p.airY=y;p.airTime=time;}else{const age=time-p.airTime,dx=x-p.airX,dy=y-p.airY;if(age<=260&&Math.abs(dx)>=38&&dy<=-10&&Math.hypot(dx,dy)>=43){const started=dx>0?this.game.kickflip():this.game.heelflip();if(started){steer=p.steer;p.airX=x;p.airY=y;p.airTime=time;}}else if(age<=240&&Math.abs(dx)>=28&&Math.abs(dx)<52&&Math.abs(dy)<=18&&this.game.nearGrindRail(150)){const started=this.game.boardslide(dx>0?1:-1);if(started){steer=p.steer;p.airX=x;p.airY=y;p.airTime=time;}}else if(age<=320&&Math.abs(dx)>=52&&Math.abs(dy)<=18){const started=this.game.oneEighty(dx>0?1:-1);if(started){steer=p.steer;p.airX=x;p.airY=y;p.airTime=time;}}else if(age>320){p.airX=x;p.airY=y;p.airTime=time;}}}else{p.airX=null;p.airY=null;p.airTime=null;}this.game.setFront(true,steer,tilt);}}
  up(id,cancelled=false,time=0){const p=this.pointers.get(id);if(!p)return;this.pointers.delete(id);this.roles[p.role]=null;if(p.role==='front')this.game.releaseFront();else if(cancelled){this.game.rear=false;this.game.catch=false;if(this.game.phase==='load'){this.game.phase='roll';this.game.charge=0;}}else{const recent=time-p.lastTime<130;const sideways=p.lastX-p.x;this.game.rearUp(1+(recent?clamp(p.velocity,0,1.5)*.08:0));if(this.game.phase==='air'&&Math.abs(sideways)>=72)this.game.threeSixtyShuvit(sideways>0?1:-1);else if(this.game.phase==='air'&&Math.abs(sideways)>=34)this.game.popShuvit(sideways>0?1:-1);}}
  clear(){this.pointers.clear();this.roles={front:null,rear:null};this.game.cancelInput();}
}

// The demo shares real physics and obstacle timing with the two-thumb game.
export function demoPop(game){
  if(game.mode!=='playing'||game.phase!=='roll')return false;
  game.rearDown();game.charge=PHYSICS.loadTime;game.rearUp(1.08);return true;
}
export function assistDemo(game){
  if(game.mode!=='playing')return;
  game.demoAssist=true;
  game.setFront(false);
  if(game.phase==='air'&&!game.catch)game.rearDown();
  if(game.phase==='roll')game.rear=false;
}
export function viewScale(width,height,locked){return clamp(locked?width/1080:Math.min(width/1080,height/540),.7,1.5);}
